const rawOutput = $input.first().json.output || '';
const telegramInput = $('Telegram Trigger').first().json.message || {};
const chatId = telegramInput.chat?.id;
const messageId = telegramInput.message_id;

// Match JSON action block
const actionRegex = /```(?:json:invoice_action|json)\s*([\s\S]*?)\s*```/;
const match = rawOutput.match(actionRegex);

if (match) {
  try {
    const data = JSON.parse(match[1]);
    const cleanMessage = rawOutput.replace(actionRegex, '').trim();
    const action = data.action || 'chat';

    if (action === 'create_invoice' && data.clientName && data.amount) {
      const today = $now.setZone('Europe/Berlin').toFormat('yyyy-MM-dd');
      const due = $now.setZone('Europe/Berlin').plus({ days: 14 }).toFormat('yyyy-MM-dd');

      let symbol = data.currencySymbol || '€';
      const curr = (data.currency || 'EUR').toUpperCase();
      if (curr === 'USD') symbol = '$';
      if (curr === 'TRY') symbol = '₺';
      if (curr === 'GBP') symbol = '£';
      if (curr === 'EUR') symbol = '€';

      return [{
        json: {
          action: 'create_invoice',
          chatId,
          messageId,
          replyText: cleanMessage,
          clientName: data.clientName,
          clientAddress: data.clientAddress || '',
          description: data.description || 'Professional Services',
          amount: Number(data.amount) || 0,
          currency: curr,
          currencySymbol: symbol,
          invoiceDate: data.invoiceDate || today,
          dueDate: data.dueDate || due,
          invoiceNumber: data.invoiceNumber || `INV-${$now.setZone('Europe/Berlin').toFormat('yyyyMMdd')}-01`,
          notes: data.notes || 'Payment due within 14 days of invoice date.'
        }
      }];
    }
  } catch (e) {
    // JSON parsing fallback
  }
}

// Conversational reply or asking for missing details
return [{
  json: {
    action: 'chat',
    chatId,
    messageId,
    replyText: rawOutput
  }
}];

// =========================================================================
// 🏢 INVOICER & BANK TRANSFER DETAILS (Edit these anytime!)
// =========================================================================
const INVOICER_CONFIG = {
  name: 'Serhat Kumas',
  title: 'Software Engineer & AI Consultant',
  company: 'Serhat Kumas Consulting',
  email: 'serhat.kumas.SK@gmail.com',
  address: 'Berlin, Germany',
  taxId: 'DE123456789', // Editable Tax / VAT ID

  // 💳 Bank Transfer & IBAN Details (Editable placeholders)
  bankName: 'Deutsche Bank / N26',
  accountHolder: 'Serhat Kumas',
  iban: 'DE89 3704 0044 0532 0130 00',
  bic: 'DBBTTDDBXXX',
  paymentTerms: 'Please transfer to the IBAN above within 14 days. Reference invoice number.'
};

const input = $input.first().json;
const invoiceNumber = input.invoiceNumber || `INV-${$now.setZone('Europe/Berlin').toFormat('yyyyMMdd')}-01`;
const invoiceDate = input.invoiceDate || $now.setZone('Europe/Berlin').toFormat('yyyy-MM-dd');
const dueDate = input.dueDate || $now.setZone('Europe/Berlin').plus({ days: 14 }).toFormat('yyyy-MM-dd');
const clientName = input.clientName || 'Client Company';
const clientAddress = input.clientAddress || 'Client Location';
const rawDescription = input.description || 'Professional Consulting Services';
const amount = Number(input.amount) || 0;
const currency = input.currency || 'EUR';
const currencySymbol = input.currencySymbol || '€';
const chatId = input.chatId;

// =========================================================================
// 📄 HIGH-QUALITY VECTOR PDF-1.4 GENERATOR ENGINE (Pure JavaScript)
// =========================================================================
function sanitizeForPdf(str) {
  if (!str) return '';
  return String(str)
    .replace(/[şŞ]/g, s => s === 'ş' ? 's' : 'S')
    .replace(/[çÇ]/g, c => c === 'ç' ? 'c' : 'C')
    .replace(/[ğĞ]/g, g => g === 'ğ' ? 'g' : 'G')
    .replace(/[ıİ]/g, i => i === 'ı' ? 'i' : 'I')
    .replace(/[öÖ]/g, o => o === 'ö' ? 'o' : 'O')
    .replace(/[üÜ]/g, u => u === 'ü' ? 'u' : 'U')
    .replace(/[^\x20-\x7E]/g, ' ')
    .replace(/\\/g, '\\\\')
    .replace(/\(/g, '\\(')
    .replace(/\)/g, '\\)');
}

function wrapText(str, maxChars = 44) {
  const words = String(str || '').split(' ');
  const lines = [];
  let currentLine = '';
  for (const word of words) {
    if ((currentLine + ' ' + word).trim().length <= maxChars) {
      currentLine = (currentLine + ' ' + word).trim();
    } else {
      if (currentLine) lines.push(currentLine);
      currentLine = word;
    }
  }
  if (currentLine) lines.push(currentLine);
  return lines;
}

function buildInvoicePdf() {
  const objects = [];
  function addObject(content) {
    objects.push(content);
    return objects.length;
  }

  // 1: Catalog
  addObject('<< /Type /Catalog /Pages 2 0 R >>');
  // 2: Pages
  addObject('<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
  // 3: Page (A4 standard: 595.28 x 841.89 points)
  addObject('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Contents 4 0 R /Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> >>');

  let stream = '';
  function rect(x, y, w, h, fillR, fillG, fillB) {
    stream += `${fillR} ${fillG} ${fillB} rg ${x} ${y} ${w} ${h} re f\n`;
  }
  function strokeRect(x, y, w, h, r, g, b, lineWidth = 1) {
    stream += `${lineWidth} w ${r} ${g} ${b} RG ${x} ${y} ${w} ${h} re S\n`;
  }
  function line(x1, y1, x2, y2, r, g, b, lineWidth = 1) {
    stream += `${lineWidth} w ${r} ${g} ${b} RG ${x1} ${y1} m ${x2} ${y2} l S\n`;
  }
  function text(font, size, x, y, str, r = 0, g = 0, b = 0) {
    const cleanStr = sanitizeForPdf(str);
    stream += `BT /${font} ${size} Tf ${r} ${g} ${b} rg 1 0 0 1 ${x} ${y} Tm (${cleanStr}) Tj ET\n`;
  }

  // Header Banner (Executive Navy)
  rect(0, 740, 595.28, 102, 0.08, 0.12, 0.22);
  rect(0, 737, 595.28, 3, 0.2, 0.5, 0.9); // Cyan accent bar

  // Header Title & Subtitle
  text('F2', 28, 45, 792, 'INVOICE', 1, 1, 1);
  text('F1', 10, 45, 772, 'Official Payment Request & Service Statement', 0.75, 0.82, 0.95);

  // Invoice Number & Dates (Top Right Header)
  text('F2', 12, 385, 802, invoiceNumber, 1, 1, 1);
  text('F1', 10, 385, 784, `Invoice Date: ${invoiceDate}`, 0.85, 0.9, 0.98);
  text('F1', 10, 385, 767, `Due Date:     ${dueDate}`, 0.98, 0.82, 0.82);

  // Billed From (Invoicer Card)
  rect(45, 625, 240, 95, 0.97, 0.98, 1.0);
  strokeRect(45, 625, 240, 95, 0.84, 0.88, 0.94, 1);
  text('F2', 9, 58, 703, 'BILLED FROM (ISSUER)', 0.35, 0.42, 0.55);
  text('F2', 12, 58, 686, INVOICER_CONFIG.name, 0.1, 0.15, 0.25);
  text('F1', 9.5, 58, 670, INVOICER_CONFIG.title, 0.35, 0.4, 0.5);
  text('F1', 9.5, 58, 654, INVOICER_CONFIG.address, 0.35, 0.4, 0.5);
  text('F1', 9.5, 58, 638, INVOICER_CONFIG.email, 0.15, 0.45, 0.8);

  // Billed To (Client Card)
  rect(310, 625, 240, 95, 0.97, 0.98, 1.0);
  strokeRect(310, 625, 240, 95, 0.84, 0.88, 0.94, 1);
  text('F2', 9, 323, 703, 'BILLED TO (CLIENT)', 0.35, 0.42, 0.55);
  text('F2', 13, 323, 684, clientName, 0.1, 0.15, 0.25);
  if (clientAddress) {
    text('F1', 9.5, 323, 668, clientAddress, 0.35, 0.4, 0.5);
  }
  text('F1', 9.5, 323, 652, 'Status: Payment Pending', 0.85, 0.4, 0.1);
  text('F1', 9.5, 323, 636, 'Payment Terms: Net 14 Days', 0.35, 0.4, 0.5);

  // Table Header Bar
  rect(45, 555, 505, 30, 0.15, 0.22, 0.35);
  text('F2', 10, 60, 567, 'SERVICE / ITEM DESCRIPTION', 1, 1, 1);
  text('F2', 10, 360, 567, 'QTY', 1, 1, 1);
  text('F2', 10, 420, 567, 'UNIT PRICE', 1, 1, 1);
  text('F2', 10, 495, 567, 'AMOUNT', 1, 1, 1);

  // Clean Word-Wrapping & Dynamic Row Calculation
  const descLines = wrapText(rawDescription, 44);
  const lineCount = Math.min(descLines.length, 3);
  const rowHeight = Math.max(60, 30 + (lineCount * 14));
  const rowBottom = 555 - rowHeight;

  // Table Row background & border
  rect(45, rowBottom, 505, rowHeight, 1, 1, 1);
  strokeRect(45, rowBottom, 505, rowHeight, 0.86, 0.89, 0.94, 1);

  // Vertical column dividers to guarantee zero overlap and maximum readability
  line(345, rowBottom, 345, 555, 0.9, 0.92, 0.96, 1);
  line(405, rowBottom, 405, 555, 0.9, 0.92, 0.96, 1);
  line(480, rowBottom, 480, 555, 0.9, 0.92, 0.96, 1);

  // Render Description Lines cleanly
  const startDescY = 555 - 18;
  for (let i = 0; i < lineCount; i++) {
    text('F2', 10, 58, startDescY - (i * 14), descLines[i], 0.1, 0.15, 0.25);
  }
  if (lineCount === 1) {
    text('F1', 8.5, 58, startDescY - 15, 'Professional Services Rendered as agreed', 0.45, 0.5, 0.6);
  }

  // Centered numbers vertically in row
  const midY = rowBottom + (rowHeight / 2) - 4;
  text('F1', 10, 368, midY, '1', 0.2, 0.25, 0.35);
  text('F1', 10, 415, midY, `${amount.toFixed(2)} ${currency}`, 0.2, 0.25, 0.35);
  text('F2', 10.5, 490, midY, `${amount.toFixed(2)} ${currency}`, 0.1, 0.15, 0.25);

  // Subtotal & Total Summary Box (placed relative to rowBottom)
  const summaryTop = rowBottom - 12;
  const summaryHeight = 80;
  rect(340, summaryTop - summaryHeight, 210, summaryHeight, 0.97, 0.98, 1.0);
  strokeRect(340, summaryTop - summaryHeight, 210, summaryHeight, 0.84, 0.88, 0.94, 1);
  text('F1', 9.5, 355, summaryTop - 22, 'Subtotal:', 0.35, 0.4, 0.5);
  text('F1', 10, 465, summaryTop - 22, `${amount.toFixed(2)} ${currency}`, 0.1, 0.15, 0.25);
  text('F1', 9.5, 355, summaryTop - 42, 'Tax / VAT (0%):', 0.35, 0.4, 0.5);
  text('F1', 10, 465, summaryTop - 42, `0.00 ${currency}`, 0.1, 0.15, 0.25);
  line(355, summaryTop - 50, 535, summaryTop - 50, 0.82, 0.86, 0.92, 1);
  text('F2', 12, 355, summaryTop - 68, 'TOTAL DUE:', 0.08, 0.12, 0.22);
  text('F2', 13, 455, summaryTop - 68, `${amount.toFixed(2)} ${currency}`, 0.08, 0.5, 0.25);

  // Bank & Payment Details Box (Placed relative to summary box)
  const bankTop = summaryTop - summaryHeight - 12;
  const bankHeight = 125;
  rect(45, bankTop - bankHeight, 505, bankHeight, 0.96, 0.97, 0.99);
  strokeRect(45, bankTop - bankHeight, 505, bankHeight, 0.82, 0.86, 0.92, 1);
  rect(45, bankTop - 26, 505, 26, 0.88, 0.92, 0.98);
  text('F2', 10.5, 60, bankTop - 17, 'BANK TRANSFER & PAYMENT DETAILS', 0.15, 0.22, 0.38);

  text('F2', 9.5, 60, bankTop - 44, 'Bank Name:', 0.3, 0.35, 0.45);
  text('F1', 10, 170, bankTop - 44, INVOICER_CONFIG.bankName, 0.1, 0.15, 0.25);

  text('F2', 9.5, 60, bankTop - 64, 'Account Holder:', 0.3, 0.35, 0.45);
  text('F1', 10, 170, bankTop - 64, INVOICER_CONFIG.accountHolder, 0.1, 0.15, 0.25);

  text('F2', 9.5, 60, bankTop - 84, 'IBAN:', 0.3, 0.35, 0.45);
  text('F2', 10.5, 170, bankTop - 84, INVOICER_CONFIG.iban, 0.08, 0.35, 0.75);

  text('F2', 9.5, 60, bankTop - 104, 'BIC / SWIFT:', 0.3, 0.35, 0.45);
  text('F1', 10, 170, bankTop - 104, INVOICER_CONFIG.bic, 0.1, 0.15, 0.25);

  text('F2', 9.5, 60, bankTop - 120, 'Tax / VAT ID:', 0.3, 0.35, 0.45);
  text('F1', 9.5, 170, bankTop - 120, INVOICER_CONFIG.taxId, 0.1, 0.15, 0.25);

  // Footer Terms & Notes
  const footerY = bankTop - bankHeight - 14;
  line(45, footerY, 550, footerY, 0.88, 0.9, 0.94, 1);
  text('F2', 9.5, 45, footerY - 16, 'Payment Terms & Notes:', 0.25, 0.3, 0.4);
  text('F1', 9, 45, footerY - 30, INVOICER_CONFIG.paymentTerms, 0.4, 0.45, 0.55);
  text('F1', 9, 45, footerY - 44, 'Thank you for your business! For questions, contact ' + INVOICER_CONFIG.email, 0.4, 0.45, 0.55);

  // Subtle Bottom Signature
  text('F1', 8, 180, 25, 'Official Invoice generated on behalf of Serhat Kumas', 0.6, 0.65, 0.75);

  // 4: Content Stream Length & Endstream
  const streamLength = Buffer.byteLength(stream, 'binary');
  addObject(`<< /Length ${streamLength} >>\nstream\n${stream}endstream`);

  // 5: Font F1 (Helvetica standard)
  addObject('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
  // 6: Font F2 (Helvetica-Bold standard)
  addObject('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>');

  // Construct PDF structure
  let pdf = '%PDF-1.4\n';
  const xrefOffsets = [0];
  let currentOffset = Buffer.byteLength(pdf, 'binary');

  for (let i = 0; i < objects.length; i++) {
    xrefOffsets.push(currentOffset);
    const objStr = `${i + 1} 0 obj\n${objects[i]}\nendobj\n`;
    pdf += objStr;
    currentOffset += Buffer.byteLength(objStr, 'binary');
  }

  const xrefStart = currentOffset;
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  for (let i = 1; i <= objects.length; i++) {
    pdf += String(xrefOffsets[i]).padStart(10, '0') + ' 00000 n \n';
  }

  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefStart}\n%%EOF\n`;
  return Buffer.from(pdf, 'binary');
}

const pdfBuffer = buildInvoicePdf();
const pdfBase64 = pdfBuffer.toString('base64');
const safeFileName = `Invoice_${invoiceNumber}_${clientName.replace(/[^a-zA-Z0-9]/g, '_')}.pdf`;

return [{
  json: {
    clientName,
    invoiceNumber,
    invoiceDate,
    dueDate,
    amount,
    currency,
    currencySymbol,
    description: rawDescription,
    chatId,
    fileName: safeFileName,
    invoicer: INVOICER_CONFIG
  },
  binary: {
    data: {
      data: pdfBase64,
      mimeType: 'application/pdf',
      fileName: safeFileName,
      fileExtension: 'pdf'
    }
  }
}];

const driveData = $input.first().json;
const invoiceNode = $('Generate PDF Invoice').first();
const driveLink = driveData.webViewLink || driveData.webContentLink || (driveData.id ? `https://drive.google.com/file/d/${driveData.id}/view` : '#');

return [{
  json: {
    ...invoiceNode.json,
    driveLink
  },
  binary: {
    data: invoiceNode.binary.data
  }
}];

